pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= type(uint256).max / 2);
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);
        uint256 actual = c.currentBetLimit();
        assertEq(actual, amount);
    }
}
